// Acoustic envelope comparison only: NOT voice recognition or separation.
// in1/2: raw mic stereo; in3/4: digital reference stereo.
// in5: preflight detectpermit; in6: preflight epoch; in7: validated offset ms.
// Compare 600 ms of three-band envelopes, allowing +/-20 ms around the
// existing calibration. Four fixed stereo reference views: peak, mono, L, R.
// No fitted acoustic model, automatic offset learning or audio output.
Param profilevalid(0);
Param sourcemode(0);
// Explicit user-declared quiet capture; never infer that speakers are muted.
Param backgroundrequest(0);
// User-declared speaker reactivation. It does not change Windows or Live.
Param speakersrequest(0);
History testphase(0);
History testrequest(0);
History testgate(0);
History mutedwindows(0);
History mutedwithin(0);
History mutedabove(0);
History muteduncertain(0);
History mutedstart(0);
