// Lifetime diagnostics survive invalidations but NEVER authorize evaluation.
History runlength(0);
History longestrun(0);
History resetepisodes(0);
History previousreset(0);
History lastreason(0);
History windowscomputed(0);
History epochchanges(0);
History offsetchanges(0);
History permitlosses(0);
History profilechanges(0);
History modechanges(0);
History lastpermit(0);
History clock(0);
History mldc(0);
History mllow(0);
History mlupper(0);
History mrdc(0);
History mrlow(0);
History mrupper(0);
History rldc(0);
History rllow(0);
History rlupper(0);
History rrdc(0);
History rrlow(0);
History rrupper(0);
History rmdc(0);
History rmlow(0);
History rmupper(0);
