History rsum0(0);
Data rdata0(256);
History msum1(0);
Data mdata1(256);
History rsum1(0);
Data rdata1(256);
History msum2(0);
Data mdata2(256);
History rsum2(0);
Data rdata2(256);
History rlframe0(0);
History rlframe1(0);
History rlframe2(0);
History rrframe0(0);
History rrframe1(0);
History rrframe2(0);
History rmframe0(0);
History rmframe1(0);
History rmframe2(0);
Data rleft0(256);
Data rleft1(256);
Data rleft2(256);
Data rright0(256);
Data rright1(256);
Data rright2(256);
Data rmono0(256);
Data rmono1(256);
Data rmono2(256);

operating = (in5 == 1) && (profilevalid == 1) && (sourcemode == 1);
epochchanged = in6 != lastepoch;
// A stable anchor ignores sub-nanosecond numerical noise; cumulative drift
// still crosses the threshold. Meaningful offset edits always invalidate.
offsetchanged = abs(in7 - lastoffset) > 0.000001;
profilechanged = profilevalid != lastprofile;
modechanged = sourcemode != lastmode;
changed = epochchanged || offsetchanged || profilechanged || modechanged;
peak = max(max(abs(in1), abs(in2)), max(abs(in3), abs(in4)));
ncliphold = peak >= 0.98 ? samplerate * 0.250 : max(0, cliphold - 1);
resetnow = !operating || changed || (ncliphold > 0);
reason = (in5 != 1) + 2 * epochchanged + 4 * offsetchanged + 8 * (profilevalid != 1 || profilechanged) + 16 * (sourcemode != 1 || modechanged) + 32 * (ncliphold > 0);
nrunlength = resetnow ? 0 : min(runlength + 1, 1000000000);
nlongestrun = max(longestrun, nrunlength);
nresetepisodes = min(1000000000, resetepisodes + (resetnow && !previousreset));
nlastreason = resetnow ? reason : lastreason;
nwindowscomputed = windowscomputed;
nepochchanges = min(1000000000, epochchanges + epochchanged);
noffsetchanges = min(1000000000, offsetchanges + offsetchanged);
npermitlosses = min(1000000000, permitlosses + ((in5 != 1) && (lastpermit == 1)));
nprofilechanges = min(1000000000, profilechanges + profilechanged);
nmodechanges = min(1000000000, modechanges + modechanged);
// Smooth DC rejection and broad bands, independently per stereo channel.
c20 = exp(-6.28318530718 * 20 / samplerate);
c400 = exp(-6.28318530718 * 400 / samplerate);
c1800 = exp(-6.28318530718 * 1800 / samplerate);
nmldc = in1 + c20 * (mldc - in1);
mlhp = in1 - nmldc;
nmllow = mlhp + c400 * (mllow - mlhp);
nmlupper = mlhp + c1800 * (mlupper - mlhp);
nmrdc = in2 + c20 * (mrdc - in2);
mrhp = in2 - nmrdc;
nmrlow = mrhp + c400 * (mrlow - mrhp);
nmrupper = mrhp + c1800 * (mrupper - mrhp);
nrldc = in3 + c20 * (rldc - in3);
rlhp = in3 - nrldc;
nrllow = rlhp + c400 * (rllow - rlhp);
nrlupper = rlhp + c1800 * (rlupper - rlhp);
nrrdc = in4 + c20 * (rrdc - in4);
rrhp = in4 - nrrdc;
nrrlow = rrhp + c400 * (rrlow - rrhp);
nrrupper = rrhp + c1800 * (rrupper - rrhp);
// Mix before rectification: summing envelopes would miss stereo cancellation.
rm = (in3 + in4) * 0.5;
nrmdc = rm + c20 * (rmdc - rm);
rmhp = rm - nrmdc;
nrmlow = rmhp + c400 * (rmlow - rmhp);
nrmupper = rmhp + c1800 * (rmupper - rmhp);
nrlframe0 = rlframe0 + abs(nrllow);
nrlframe1 = rlframe1 + abs(nrlupper - nrllow);
nrlframe2 = rlframe2 + abs(rlhp - nrlupper);
nrrframe0 = rrframe0 + abs(nrrlow);
nrrframe1 = rrframe1 + abs(nrrupper - nrrlow);
nrrframe2 = rrframe2 + abs(rrhp - nrrupper);
nrmframe0 = rmframe0 + abs(nrmlow);
nrmframe1 = rmframe1 + abs(nrmupper - nrmlow);
nrmframe2 = rmframe2 + abs(rmhp - nrmupper);
nmsum0 = msum0 + max(abs(nmllow), abs(nmrlow));
nmsum1 = msum1 + max(abs(nmlupper - nmllow), abs(nmrupper - nmrlow));
nmsum2 = msum2 + max(abs(mlhp - nmlupper), abs(mrhp - nmrupper));
nrsum0 = rsum0 + max(abs(nrllow), abs(nrrlow));
nrsum1 = rsum1 + max(abs(nrlupper - nrllow), abs(nrrupper - nrrlow));
nrsum2 = rsum2 + max(abs(rlhp - nrlupper), abs(rrhp - nrrupper));
nframesamples = framesamples + 1;
nwritepos = writepos;
nfilled = filled;
nhop = hop;
nstate = state;
nmatch = match;
ndistinct = distinct;
ninputlevel = inputlevel;
nreflevel = reflevel;
nactivity = activity;
nmodel = bestmodel;
nlagms = bestlagms;
nbandmatch0 = bandmatch0;
nbandmatch1 = bandmatch1;
nbandmatch2 = bandmatch2;
nusablebands = usablebands;
nmicvariationindex = micvariationindex;
npeakmatch = peakmatch;
nband_input_level_low = band_input_level_low;
nband_input_level_mid = band_input_level_mid;
nband_input_level_high = band_input_level_high;
nband_reference_level_low = band_reference_level_low;
nband_reference_level_mid = band_reference_level_mid;
nband_reference_level_high = band_reference_level_high;
nband_input_variation_low = band_input_variation_low;
nband_input_variation_mid = band_input_variation_mid;
nband_input_variation_high = band_input_variation_high;
nband_reference_variation_low = band_reference_variation_low;
nband_reference_variation_mid = band_reference_variation_mid;
nband_reference_variation_high = band_reference_variation_high;
nband_weight_low = band_weight_low;
nband_weight_mid = band_weight_mid;
nband_weight_high = band_weight_high;
nusable_band_mask = usable_band_mask;
nreference_supported_band_mask = reference_supported_band_mask;
npartial_reference_windows = partial_reference_windows;
nband_reference_windows_low = band_reference_windows_low;
nband_reference_windows_mid = band_reference_windows_mid;
nband_reference_windows_high = band_reference_windows_high;
nlastclass = lastclass;
nclassrun = classrun;
nreferencewindows = referencewindows;
ndistinctwindows = distinctwindows;
nuncertainwindows = uncertainwindows;
// The background profile is session/context-scoped and diagnostic only.
// Starting a new request discards the partial leading 10 ms frame and waits
// at least 500 ms so the button click is not part of the declared baseline.
framelen = max(1, floor(samplerate * 0.010));
nbgstate = bgstate;
nbgrequest = bgrequest;
nbgcount = bgcount;
nbgskipframe = bgskipframe;
nbgmean0 = bgmean0;
nbgmean1 = bgmean1;
nbgmean2 = bgmean2;
nbgm20 = bgm20;
nbgm21 = bgm21;
nbgm22 = bgm22;
nbgcmpstate = bgcmpstate;
nbgcmpcount = bgcmpcount;
nbgcmpframes = bgcmpframes;
nbgcmpwindows = bgcmpwindows;
nbgcmpmask = bgcmpmask;
nbgcmpend = bgcmpend;
nbgcmpwithin = bgcmpwithin;
nbgcmpabove = bgcmpabove;
nbgcmpuncertain = bgcmpuncertain;
nbgcmpsum0 = bgcmpsum0;
nbgcmpexceed0 = bgcmpexceed0;
nbgcmplevel0 = bgcmplevel0;
nbgcmpfraction0 = bgcmpfraction0;
nbgcmpsum1 = bgcmpsum1;
nbgcmpexceed1 = bgcmpexceed1;
nbgcmplevel1 = bgcmplevel1;
nbgcmpfraction1 = bgcmpfraction1;
nbgcmpsum2 = bgcmpsum2;
nbgcmpexceed2 = bgcmpexceed2;
nbgcmplevel2 = bgcmplevel2;
nbgcmpfraction2 = bgcmpfraction2;
bgnewrequest = backgroundrequest != bgrequest;
if (bgnewrequest) {
    nbgstate = backgroundrequest > 0 ? 1 : 0;
    nbgrequest = backgroundrequest;
    nbgcount = 0;
    nbgskipframe = 1 + floor(samplerate * 0.5 / framelen + 0.999999999);
    nbgmean0 = 0;
    nbgmean1 = 0;
    nbgmean2 = 0;
    nbgm20 = 0;
    nbgm21 = 0;
    nbgm22 = 0;
}
if (resetnow) {
    nbgstate = (bgstate != 0 || bgnewrequest) ? 3 : 0;
    nbgcount = 0;
    nbgskipframe = 0;
    nbgmean0 = 0;
    nbgmean1 = 0;
    nbgmean2 = 0;
    nbgm20 = 0;
    nbgm21 = 0;
    nbgm22 = 0;
}
// Heuristic limits on the SAME disjoint 10 ms envelopes as acquisition.
// Three population SDs is a margin, NOT a confidence interval or voice test.
// Relative/absolute floors avoid hypersensitivity to constant/zero baselines.
bgcmplimit0 = nbgmean0 + max(0.00001, max(0.1 * nbgmean0, 3 * sqrt(max(0, nbgm20 / max(1, nbgcount)))));
bgcmplimit1 = nbgmean1 + max(0.00001, max(0.1 * nbgmean1, 3 * sqrt(max(0, nbgm21 / max(1, nbgcount)))));
bgcmplimit2 = nbgmean2 + max(0.00001, max(0.1 * nbgmean2, 3 * sqrt(max(0, nbgm22 / max(1, nbgcount)))));
if (resetnow || bgnewrequest || (nbgstate != 2)) {
    nbgcmpstate = 0;
    nbgcmpcount = 0;
    nbgcmpframes = 0;
    nbgcmpwindows = 0;
    nbgcmpmask = 0;
    nbgcmpend = 0;
    nbgcmpwithin = 0;
    nbgcmpabove = 0;
    nbgcmpuncertain = 0;
    nbgcmpsum0 = 0;
    nbgcmpexceed0 = 0;
    nbgcmplevel0 = 0;
    nbgcmpfraction0 = 0;
    nbgcmpsum1 = 0;
    nbgcmpexceed1 = 0;
    nbgcmplevel1 = 0;
    nbgcmpfraction1 = 0;
    nbgcmpsum2 = 0;
    nbgcmpexceed2 = 0;
    nbgcmplevel2 = 0;
    nbgcmpfraction2 = 0;
}
// Separate declared-condition phases. No mute inference and no timed
// assumption about when the user reactivates the speakers.
ntestphase = testphase;
ntestrequest = testrequest;
ntestgate = testgate;
nmutedwindows = mutedwindows;
nmutedwithin = mutedwithin;
nmutedabove = mutedabove;
nmuteduncertain = muteduncertain;
nmutedstart = mutedstart;
nmutedend = mutedend;
nmutedmean0 = mutedmean0;
nmutedfraction0 = mutedfraction0;
nmutedbandwindows0 = mutedbandwindows0;
nmutedmean1 = mutedmean1;
nmutedfraction1 = mutedfraction1;
nmutedbandwindows1 = mutedbandwindows1;
nmutedmean2 = mutedmean2;
nmutedfraction2 = mutedfraction2;
nmutedbandwindows2 = mutedbandwindows2;
naudiblewindows = audiblewindows;
naudiblewithin = audiblewithin;
naudibleabove = audibleabove;
naudibleuncertain = audibleuncertain;
naudiblestart = audiblestart;
naudibleend = audibleend;
naudiblemean0 = audiblemean0;
naudiblefraction0 = audiblefraction0;
naudiblebandwindows0 = audiblebandwindows0;
naudiblemean1 = audiblemean1;
naudiblefraction1 = audiblefraction1;
naudiblebandwindows1 = audiblebandwindows1;
naudiblemean2 = audiblemean2;
naudiblefraction2 = audiblefraction2;
naudiblebandwindows2 = audiblebandwindows2;
testnewrequest = speakersrequest != testrequest;
ntestrequest = speakersrequest;
if (bgnewrequest || resetnow || (nbgstate != 2)) {
    ntestphase = 0;
    ntestgate = 0;
    nmutedwindows = 0;
    nmutedwithin = 0;
    nmutedabove = 0;
    nmuteduncertain = 0;
    nmutedstart = 0;
    nmutedend = 0;
    nmutedmean0 = 0;
    nmutedfraction0 = 0;
    nmutedbandwindows0 = 0;
    nmutedmean1 = 0;
    nmutedfraction1 = 0;
    nmutedbandwindows1 = 0;
    nmutedmean2 = 0;
    nmutedfraction2 = 0;
    nmutedbandwindows2 = 0;
    naudiblewindows = 0;
    naudiblewithin = 0;
    naudibleabove = 0;
    naudibleuncertain = 0;
    naudiblestart = 0;
    naudibleend = 0;
    naudiblemean0 = 0;
    naudiblefraction0 = 0;
    naudiblebandwindows0 = 0;
    naudiblemean1 = 0;
    naudiblefraction1 = 0;
    naudiblebandwindows1 = 0;
    naudiblemean2 = 0;
    naudiblefraction2 = 0;
    naudiblebandwindows2 = 0;
    ntestphase = (nbgstate == 3) ? 6 : 0;
} else if (testnewrequest && (testphase == 2) && (speakersrequest > 0)) {
    // Wait at least 500 ms after the declaration/click. Accept only comparison
    // windows whose ENTIRE raw envelope span begins after this gate.
    ntestphase = 3;
    ntestgate = clock + floor(samplerate * 0.5 + 0.999999999);
} else if ((testphase == 3) && (clock >= testgate)) {
    ntestphase = 4;
}
framems = 1000 * framelen / samplerate;
// Signed offsets: delay the reference for positive offsets and microphone
// envelopes for negative offsets. Never read unwritten or previous-epoch data.
rdelay = floor(max(0, clamp(in7, -500, 500)) / framems + 0.5);
mdelay = floor(max(0, -clamp(in7, -500, 500)) / framems + 0.5);
if (resetnow) {
    nframesamples = 0;
    nwritepos = 0;
    nfilled = 0;
    nhop = 0;
    nstate = 1;
    nmatch = 0;
    ndistinct = 0;
    ninputlevel = 0;
    nreflevel = 0;
    nactivity = 0;
    nmodel = 0;
    nlagms = 0;
    nbandmatch0 = 0;
    nbandmatch1 = 0;
    nbandmatch2 = 0;
    nusablebands = 0;
    nmicvariationindex = 0;
    npeakmatch = 0;
    nband_input_level_low = 0;
    nband_input_level_mid = 0;
    nband_input_level_high = 0;
    nband_reference_level_low = 0;
    nband_reference_level_mid = 0;
    nband_reference_level_high = 0;
    nband_input_variation_low = 0;
    nband_input_variation_mid = 0;
    nband_input_variation_high = 0;
    nband_reference_variation_low = 0;
    nband_reference_variation_mid = 0;
    nband_reference_variation_high = 0;
    nband_weight_low = 0;
    nband_weight_mid = 0;
    nband_weight_high = 0;
    nusable_band_mask = 0;
    nreference_supported_band_mask = 0;
    npartial_reference_windows = 0;
    nband_reference_windows_low = 0;
    nband_reference_windows_mid = 0;
    nband_reference_windows_high = 0;
    nlastclass = 0;
    nclassrun = 0;
    nreferencewindows = 0;
    ndistinctwindows = 0;
    nuncertainwindows = 0;
    nmsum0 = 0;
    nrsum0 = 0;
    nmsum1 = 0;
    nrsum1 = 0;
    nmsum2 = 0;
    nrsum2 = 0;
    nmldc = 0;
    nmllow = 0;
    nmlupper = 0;
    nmrdc = 0;
    nmrlow = 0;
    nmrupper = 0;
    nrldc = 0;
    nrllow = 0;
    nrlupper = 0;
    nrrdc = 0;
    nrrlow = 0;
    nrrupper = 0;
    nrmdc = 0;
    nrmlow = 0;
    nrmupper = 0;
    nrlframe0 = 0; nrlframe1 = 0; nrlframe2 = 0;
    nrrframe0 = 0; nrrframe1 = 0; nrrframe2 = 0;
    nrmframe0 = 0; nrmframe1 = 0; nrmframe2 = 0;
} else if (nframesamples >= framelen) {
    // Capture disjoint complete microphone frames, independent of reference
    // matching, lag selection, or overlapping comparison windows. Welford
    // moments retain the mean and population variance without cancellation.
    if (nbgstate == 1) {
        if (nbgskipframe > 0) { nbgskipframe = nbgskipframe - 1; }
        else {
            nbgcount = nbgcount + 1;
            bgvalue0 = nmsum0 / nframesamples;
            bgdelta0 = bgvalue0 - nbgmean0;
            nbgmean0 = nbgmean0 + bgdelta0 / nbgcount;
            nbgm20 = nbgm20 + bgdelta0 * (bgvalue0 - nbgmean0);
            bgvalue1 = nmsum1 / nframesamples;
            bgdelta1 = bgvalue1 - nbgmean1;
            nbgmean1 = nbgmean1 + bgdelta1 / nbgcount;
            nbgm21 = nbgm21 + bgdelta1 * (bgvalue1 - nbgmean1);
            bgvalue2 = nmsum2 / nframesamples;
            bgdelta2 = bgvalue2 - nbgmean2;
            nbgmean2 = nbgmean2 + bgdelta2 / nbgcount;
            nbgm22 = nbgm22 + bgdelta2 * (bgvalue2 - nbgmean2);
            if (nbgcount * framelen >= samplerate * 5) { nbgstate = 2; }
        }
    }

    // Start on the first full frame AFTER acquisition; never compare the
    // acquisition's final frame with a baseline containing that same frame.
    if ((bgstate == 2) && (nbgstate == 2) && !bgnewrequest) {
        nbgcmpstate = bgcmpstate == 0 ? 1 : bgcmpstate;
        nbgcmpcount = bgcmpcount + 1;
        nbgcmpsum0 = bgcmpsum0 + nmsum0 / nframesamples;
        nbgcmpexceed0 = bgcmpexceed0 + (nmsum0 / nframesamples > bgcmplimit0);
        nbgcmpsum1 = bgcmpsum1 + nmsum1 / nframesamples;
        nbgcmpexceed1 = bgcmpexceed1 + (nmsum1 / nframesamples > bgcmplimit1);
        nbgcmpsum2 = bgcmpsum2 + nmsum2 / nframesamples;
        nbgcmpexceed2 = bgcmpexceed2 + (nmsum2 / nframesamples > bgcmplimit2);
        if (nbgcmpcount * framelen >= samplerate) {
            nbgcmpframes = nbgcmpcount;
            nbgcmpwindows = min(1000000000, bgcmpwindows + 1);
            nbgcmpend = clock;
            nbgcmplevel0 = nbgcmpsum0 / nbgcmpcount;
            nbgcmpfraction0 = nbgcmpexceed0 / nbgcmpcount;
            nbgcmplevel1 = nbgcmpsum1 / nbgcmpcount;
            nbgcmpfraction1 = nbgcmpexceed1 / nbgcmpcount;
            nbgcmplevel2 = nbgcmpsum2 / nbgcmpcount;
            nbgcmpfraction2 = nbgcmpexceed2 / nbgcmpcount;
            // >=60% over the limit is persistent in this one-second window.
            // <=10% in every band is within; intermediate occupancy is uncertain.
            nbgcmpmask = (nbgcmpfraction0 >= 0.6) + 2 * (nbgcmpfraction1 >= 0.6) + 4 * (nbgcmpfraction2 >= 0.6);
            bgcmpquiet = max(nbgcmpfraction0, max(nbgcmpfraction1, nbgcmpfraction2)) <= 0.1;
            nbgcmpstate = nbgcmpmask > 0 ? 3 : (bgcmpquiet ? 2 : 4);
            nbgcmpwithin = min(1000000000, bgcmpwithin + (nbgcmpstate == 2));
            nbgcmpabove = min(1000000000, bgcmpabove + (nbgcmpstate == 3));
            nbgcmpuncertain = min(1000000000, bgcmpuncertain + (nbgcmpstate == 4));
            nbgcmpcount = 0;
            nbgcmpsum0 = 0; nbgcmpexceed0 = 0;
            nbgcmpsum1 = 0; nbgcmpexceed1 = 0;
            nbgcmpsum2 = 0; nbgcmpexceed2 = 0;
        }
    }

    poke(mdata0, nmsum0 / nframesamples, writepos);
    poke(rdata0, nrsum0 / nframesamples, writepos);
    poke(mdata1, nmsum1 / nframesamples, writepos);
    poke(rdata1, nrsum1 / nframesamples, writepos);
    poke(mdata2, nmsum2 / nframesamples, writepos);
    poke(rdata2, nrsum2 / nframesamples, writepos);
    poke(rleft0, nrlframe0 / nframesamples, writepos);
    poke(rleft1, nrlframe1 / nframesamples, writepos);
    poke(rleft2, nrlframe2 / nframesamples, writepos);
    poke(rright0, nrrframe0 / nframesamples, writepos);
    poke(rright1, nrrframe1 / nframesamples, writepos);
    poke(rright2, nrrframe2 / nframesamples, writepos);
    poke(rmono0, nrmframe0 / nframesamples, writepos);
    poke(rmono1, nrmframe1 / nframesamples, writepos);
